#!/usr/bin/env node
/**
 * Log Hub tool-wrapper verification — runner (generated by the Log Hub repo's
 * scripts/tool-wrap-check/create-check-project.mjs; re-running that script refreshes this file).
 *
 *   node run-check.mjs                        host run: the fidelity test in this machine's shells
 *   node run-check.mjs --linux [--image IMG]  the same test in a Linux container
 *   node run-check.mjs --live [--claude-home DIR]
 *                                             a live `claude -p` session in log-hub-dev:latest
 *
 * Every run writes into a new `runs/<timestamp>-<kind>/` folder. Nothing is ever deleted: old runs
 * are left for the owner to remove by hand. Exit code: 0 = all passed, 1 = a failure, 2 = the
 * environment is missing (Docker not running, image or Claude profile not found).
 *
 * Node.js built-ins only; synchronous throughout.
 */
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const PROJECT_DIR = path.dirname(fileURLToPath(import.meta.url));
const CONFIG = JSON.parse(fs.readFileSync(path.join(PROJECT_DIR, 'check.config.json'), 'utf8'));
const FIDELITY_TEST_REL = 'hook/.claude/telemetry_tool/__tests__/tool-wrap-fidelity.algo.test.js';
const LIVE_PROMPT = 'Run these three Bash commands one after the other: `zz | head -1`, `ls /nonexistent` and `find /nonexistent`. '
  + 'Do not run anything else. Then reply DONE.';
const LIVE_TIMEOUT_MS = 300000;
const SESSION_ID_PATTERN = /^[A-Za-z0-9-]{8,128}$/;

function parseArgs(argv) {
  const out = { linux: false, live: false, image: null, claudeHome: null };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--linux') out.linux = true;
    else if (a === '--live') out.live = true;
    else if (a === '--image') out.image = argv[++i] || null;
    else if (a === '--claude-home') out.claudeHome = argv[++i] || null;
    else {
      process.stderr.write(`run-check: unknown argument ${a}\n`);
      process.exit(1);
    }
  }
  return out;
}

function timestamp() {
  return new Date().toISOString().replace(/[-:]/g, '').replace(/\..*$/, '').replace('T', '-');
}

function slug(s) {
  return String(s).replace(/[^A-Za-z0-9.-]+/g, '_');
}

/** Exit 2 with one clear line when Docker is not usable. */
function requireDocker() {
  const res = spawnSync('docker', ['info', '--format', '{{.ServerVersion}}'], { encoding: 'utf8', windowsHide: true });
  if (res.error || res.status !== 0) {
    process.stderr.write('run-check: Docker is not running (or not installed) — start Docker and run again. No host fallback.\n');
    process.exit(2);
  }
}

function printTable(runDir) {
  const file = path.join(runDir, 'fidelity-results.json');
  let results;
  try {
    results = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    process.stdout.write(`\nno results file at ${file}\n`);
    return;
  }
  process.stdout.write(`\nTool-wrapper fidelity — ${results.platform}, node ${results.node}\n`);
  process.stdout.write(`shells: bash=${results.shells.bash || '-'} powershell=${results.shells.powershell || '-'} pwsh=${results.shells.pwsh || '-'}\n\n`);
  for (const [id, r] of Object.entries(results.rows)) {
    const reason = r.reason ? `  ${r.reason.split('\n')[0]}` : '';
    process.stdout.write(`  ${id.padEnd(7)} ${r.status.padEnd(8)}${reason}\n`);
  }
  for (const [id, r] of Object.entries(results.rows)) {
    if (!r.measure) continue;
    const diff = r.measure.wrappedMedianMs - r.measure.unwrappedMedianMs;
    process.stdout.write(`\nwrapper overhead (${id}, median of ${r.measure.runs}): unwrapped ${r.measure.unwrappedMedianMs} ms, `
      + `wrapped ${r.measure.wrappedMedianMs} ms, +${diff} ms\n`);
  }
  process.stdout.write(`\nresults: ${file}\n`);
}

function runHost() {
  const runDir = path.join(PROJECT_DIR, 'runs', `${timestamp()}-host`);
  fs.mkdirSync(runDir, { recursive: true });
  const res = spawnSync(process.execPath, ['--test', path.join(CONFIG.repoRoot, ...FIDELITY_TEST_REL.split('/'))], {
    stdio: 'inherit',
    env: {
      ...process.env,
      LOGHUB_FIDELITY_TEST: '1',
      LOGHUB_FIDELITY_PROJECT: PROJECT_DIR,
      LOGHUB_FIDELITY_RUN_DIR: runDir,
    },
  });
  printTable(runDir);
  return res.status === 0 ? 0 : 1;
}

function runLinux(args) {
  requireDocker();
  let image = args.image;
  if (!image) {
    image = CONFIG.linuxImage;
    process.stdout.write(`building ${image} from linux/Dockerfile ...\n`);
    const build = spawnSync('docker', ['build', '-t', image, path.join(PROJECT_DIR, 'linux')], { stdio: 'inherit', windowsHide: true });
    if (build.status !== 0) {
      process.stderr.write('run-check: docker build failed\n');
      return 1;
    }
  }
  const ts = timestamp();
  const runName = `${ts}-linux-${slug(image)}`;
  const runDir = path.join(PROJECT_DIR, 'runs', runName);
  fs.mkdirSync(runDir, { recursive: true });
  // busybox images have no bash; install it inside the throw-away container only.
  const prep = /alpine/i.test(image) ? 'apk add --no-cache bash >/dev/null && ' : '';
  const dockerArgs = [
    'run', '--rm', '--name', `loghub-twc-${ts}`,
    '--mount', `type=bind,source=${CONFIG.repoRoot},target=/repo,readonly`,
    '--mount', `type=bind,source=${PROJECT_DIR},target=/work`,
    '-e', 'LOGHUB_FIDELITY_TEST=1',
    '-e', 'LOGHUB_FIDELITY_PROJECT=/work',
    '-e', `LOGHUB_FIDELITY_RUN_DIR=/work/runs/${runName}`,
    '-w', '/work',
    image,
    'sh', '-c', `${prep}node --test /repo/${FIDELITY_TEST_REL}`,
  ];
  const res = spawnSync('docker', dockerArgs, { stdio: 'inherit', windowsHide: true });
  printTable(runDir);
  return res.status === 0 ? 0 : 1;
}

/** The merged records of every call under `<sessionDir>/calls`. */
function readCalls(sessionDir) {
  const callsDir = path.join(sessionDir, 'calls');
  let names = [];
  try {
    names = fs.readdirSync(callsDir).filter((n) => n.endsWith('.jsonl')).sort();
  } catch {
    return [];
  }
  return names.map((n) => {
    const call = { callId: n.slice(0, -'.jsonl'.length), hasExit: false, exitCode: null };
    for (const line of fs.readFileSync(path.join(callsDir, n), 'utf8').split('\n')) {
      if (!line.trim()) continue;
      let rec;
      try {
        rec = JSON.parse(line);
      } catch {
        continue;
      }
      if (rec.type === 'start') Object.assign(call, { tool: rec.tool, args: rec.args, shell: rec.shell });
      else if (rec.type === 'stream_end') {
        Object.assign(call, {
          stdoutBytes: rec.stdoutBytes,
          capturedBytes: rec.capturedBytes,
          consumerClosed: rec.consumerClosed,
          truncated: rec.truncated,
        });
      } else if (rec.type === 'exit') Object.assign(call, { hasExit: true, exitCode: rec.exitCode });
    }
    return call;
  });
}

function readJsonOrNull(file) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    return null;
  }
}

function runLive(args) {
  requireDocker();
  const image = CONFIG.liveImage;
  const inspect = spawnSync('docker', ['image', 'inspect', image], { stdio: 'ignore', windowsHide: true });
  if (inspect.status !== 0) {
    process.stderr.write(`run-check: image ${image} not found — build the Log Hub dev image first (docs/knowledgebase/docker-dev-container.md).\n`);
    return 2;
  }
  const claudeHome = path.resolve(args.claudeHome || CONFIG.claudeHome);
  if (!fs.existsSync(claudeHome)) {
    process.stderr.write(`run-check: Claude profile ${claudeHome} not found (pass --claude-home DIR).\n`);
    return 2;
  }

  // Seed the config cache, so SessionStart wraps zz, ls and find without a Log Hub server (DD-16).
  const toolWrapDir = path.join(PROJECT_DIR, '.artisyn', 'ai_work_dir', 'tool-wrap');
  fs.mkdirSync(toolWrapDir, { recursive: true });
  fs.writeFileSync(path.join(toolWrapDir, 'config-cache.json'), JSON.stringify({
    schemaVersion: 1,
    paused: false,
    tools: [{ name: 'zz', capture: 'full' }, { name: 'ls', capture: 'full' }, { name: 'find', capture: 'full' }],
  }, null, 2) + '\n');

  const ts = timestamp();
  const runDir = path.join(PROJECT_DIR, 'runs', `${ts}-live`);
  fs.mkdirSync(runDir, { recursive: true });
  const startedAtMs = Date.now();
  const before = new Set(safeReaddir(toolWrapDir));

  const script = 'export PATH="/work/bin:$PATH"; cd /work && '
    // The prompt goes first: --allowedTools takes a list and would swallow it.
    + 'claude -p "$LIVE_PROMPT" --settings /work/linux/live-settings.json --allowedTools Bash';
  const dockerArgs = [
    'run', '--rm', '--init', '--name', `loghub-twc-live-${ts}`,
    '--entrypoint', 'bash', '-u', '1000',
    '-e', 'CLAUDE_CONFIG_DIR=/home/dev/.claude-home',
    '-e', `LIVE_PROMPT=${LIVE_PROMPT}`,
    '--mount', `type=bind,source=${claudeHome},target=/home/dev/.claude-home`,
    '--mount', `type=bind,source=${CONFIG.hookDir},target=/hook,readonly`,
    '--mount', `type=bind,source=${PROJECT_DIR},target=/work`,
    '-w', '/work',
    image,
    '-lc', script,
  ];
  process.stdout.write(`running a live claude -p session in ${image} ...\n`);
  const res = spawnSync('docker', dockerArgs, {
    encoding: 'utf8',
    timeout: LIVE_TIMEOUT_MS,
    windowsHide: true,
    env: { ...process.env, MSYS_NO_PATHCONV: '1' },
  });

  const sessions = safeReaddir(toolWrapDir)
    .filter((n) => SESSION_ID_PATTERN.test(n) && !before.has(n))
    .map((n) => path.join(toolWrapDir, n))
    .filter((d) => {
      try {
        return fs.statSync(d).isDirectory() && fs.statSync(d).mtimeMs >= startedAtMs - 1000;
      } catch {
        return false;
      }
    });
  const calls = sessions.flatMap((d) => readCalls(d).map((c) => ({ sessionId: path.basename(d), ...c })));
  const zz = calls.find((c) => c.tool === 'zz');
  const ls = calls.find((c) => c.tool === 'ls');
  const find = calls.find((c) => c.tool === 'find');
  const checks = {
    claudeExit0: res.status === 0,
    zzRecorded: !!zz,
    zzConsumerClosed: !!zz && zz.consumerClosed === true,
    lsRecorded: !!ls,
    lsExitNonZero: !!ls && typeof ls.exitCode === 'number' && ls.exitCode !== 0,
  };
  // Informational only: Claude Code's Bash tool defines `find` (and `grep`) as shell functions
  // running its embedded bfs / ugrep, and a function always wins over a PATH shim.
  const info = {
    findRecorded: !!find,
    findExit1: !!find && find.exitCode === 1,
  };
  const ok = Object.values(checks).every(Boolean);
  const result = {
    ok,
    image,
    startedAt: new Date(startedAtMs).toISOString(),
    finishedAt: new Date().toISOString(),
    claudeExitCode: res.status,
    error: res.error ? String(res.error.message) : null,
    checks,
    info,
    sessions: sessions.map((d) => ({ sessionId: path.basename(d), preflight: readJsonOrNull(path.join(d, 'preflight.json')) })),
    calls,
    stdoutTail: String(res.stdout || '').slice(-2000),
    stderrTail: String(res.stderr || '').slice(-2000),
  };
  fs.writeFileSync(path.join(runDir, 'live.json'), JSON.stringify(result, null, 2) + '\n');
  process.stdout.write(`\nLive Linux session — ${ok ? 'PASS' : 'FAIL'}\n`);
  for (const [k, v] of Object.entries(checks)) process.stdout.write(`  ${k.padEnd(18)} ${v ? 'ok' : 'FAILED'}\n`);
  for (const [k, v] of Object.entries(info)) process.stdout.write(`  ${k.padEnd(18)} ${v ? 'yes' : 'no'} (informational)\n`);
  process.stdout.write(`\nresult: ${path.join(runDir, 'live.json')}\n`);
  return ok ? 0 : 1;
}

function safeReaddir(dir) {
  try {
    return fs.readdirSync(dir);
  } catch {
    return [];
  }
}

try {
  const args = parseArgs(process.argv.slice(2));
  let code;
  if (args.live) code = runLive(args);
  else if (args.linux) code = runLinux(args);
  else code = runHost();
  process.exit(code);
} catch (err) {
  process.stderr.write(`run-check error: ${err && err.message}\n`);
  process.exit(1);
}
